# DEMIURGE - art/units-land/build_units-land.py
# Land units (family Unit): every mesh, LOD, the shared trim sheet, materials, FBX exports, the manifest
# and the preview renders are generated by this one script. Never hand-edit an export: change this and rerun.
#
#   blender -b --python build_units-land.py -- [--build] [--textures] [--render] [--assets a,b] [--views 40m,300m,1km]
#
#   --build     generate meshes, export FBX (one per mesh with its LOD group), merge manifest.json, save the .blend
#   --textures  regenerate the trim sheet (done automatically when a texture is missing)
#   --render    render previews to shots/asset-units-land-<asset>-<view>.png (run through tools/render_slot.py)
#   --assets    comma list of short names (see ASSETS below, e.g. settlers-ancient,ark-intact); default all
#
# Conventions (docs/ASSETS.md): 1 BU = 1 m, Z up, front faces -Y, pivot at the centre of the footprint at
# ground level. Units are authored facing +X and turned -90 deg about Z at the end.
import bpy
import json
import math
import os
import random
import sys
import time
from mathutils import Matrix, Vector

