    prof_closed = prof
    secs = [(-3.3, 1.02, 1.0, 0, 1.3), (-2.3, 1.06, 1.08, 0, 1.3), (-0.1, 1.06, 1.08, 0, 1.3), (0.9, 1.0, 0.98, 0, 1.3)] if L == 0 else [(-3.3, 1.04, 1.0, 0, 1.3), (0.9, 1.04, 1.0, 0, 1.3)]
    m.loft(prof_closed, secs, 'canvas', smooth=(L == 0))
