def engine_pod(m, L, c, r, length, glow_front=True):
    c = V(c)
    n = [10, 6, 4, 4][L]
    a, b = c + Vector((length / 2, 0, 0)), c - Vector((length / 2, 0, 0))
    m.tube(b, a, r * 0.85, r, n, 'hull_white', caps=(False, False), smooth=L == 0)
    m.tube(a, a + Vector((0.35 * r, 0, 0)), r, r * 0.7, n, 'emit_blue' if glow_front else 'hull_white', caps=(False, True))
    m.tube(b, b - Vector((0.3 * r, 0, 0)), r * 0.85, r * 0.75, n, 'emit_blue', caps=(False, True))


def settlers_space(L, var):
    """Space settlers: a white lifting-body aerial transport with blue engine pods, hovering 4 m up."""
    m = MB()
    hz = 4.0
    n = [16, 10, 6, 4][L]
    prof, sws = [], []
    for i in range(n):
        a = 2 * math.pi * i / n
        prof.append((math.cos(a) * 2.3, math.sin(a) * 1.1))
        am = 2 * math.pi * (i + 0.5) / n
        if L <= 2 and abs(math.cos(am)) > 0.75 and -0.45 < math.sin(am) < 0.3:
            sws.append('cult_paint')
        else:
            sws.append('hull_white')
    if L == 0:
        secs = [(-8.0, 0.25, 0.35, 0, 0.35), (-7.0, 0.62, 0.7, 0, 0.2), (-4.0, 0.95, 0.95, 0, 0), (2.5, 1.0, 1.0, 0, 0), (5.8, 0.75, 0.78, 0, -0.05), (7.6, 0.38, 0.45, 0, -0.15), (8.2, 0.1, 0.15, 0, -0.2)]
    elif L == 1:
        secs = [(-8.0, 0.3, 0.4, 0, 0.3), (-4.0, 0.95, 0.95, 0, 0), (3.0, 1.0, 1.0, 0, 0), (7.0, 0.5, 0.55, 0, -0.1), (8.2, 0.12, 0.15, 0, -0.2)]
    else:
        secs = [(-8.0, 0.35, 0.45, 0, 0.3), (0.0, 1.0, 1.0, 0, 0), (8.2, 0.15, 0.2, 0, -0.2)]
    m.loft(prof, [(x, sy, sz, oy, oz + hz) for x, sy, sz, oy, oz in secs], sws, smooth=(L <= 1), swcap='hull_white')
    if L <= 1:
        # canopy blister on the nose, a culture dorsal fin, a rear drive strip
        k = 8 if L == 0 else 4
        cp = [(math.cos(math.pi * i / k) * 0.75, math.sin(math.pi * i / k) * 0.42) for i in range(k + 1)]
        m.loft(cp, [(2.6, 0.3, 0.3, 0, hz + 1.02), (4.0, 1.0, 1.0, 0, hz + 0.98), (5.4, 0.85, 0.8, 0, hz + 0.84), (6.6, 0.2, 0.2, 0, hz + 0.62)], 'glass', smooth=True)
        m.slab([(-4.6, 0, hz + 1.02), (-6.9, 0, hz + 0.86), (-7.7, 0, hz + 2.1), (-6.5, 0, hz + 2.15)], 0.12, 'cult_paint', sw_edge='hull_white')
        m.box((-8.0, 0, hz + 0.35), (0.12, 0.9, 0.35), 'emit_blue')
    for s in (-1, 1):
        if L <= 2:
            m.box((-1.0, s * 2.9, hz - 0.1), (2.4, 1.6, 0.18), 'hull_white', top_scale=(0.7, 1.0))
        engine_pod(m, L, (-1.0, s * 3.75, hz - 0.1), 0.55, 4.2)
    return m


