def track(m, L, x0, x1, gauge=1.45):
    """Ballast strip with sleepers in the texture and two rails (moves with the train)."""
    seg = 4.0
    x = x0
    while x < x1 - 1e-3:
        xe = min(x1, x + seg)
        # only the two ends of the strip get end faces (verify fix 2026-11-19: every 4 m segment had two hidden
        # coincident end faces inside the ballast)
        ends = ((3,) if xe >= x1 - 1e-3 else ()) + ((5,) if x <= x0 + 1e-3 else ())
        m.box(((x + xe) / 2, 0, 0.1), (xe - x, 3.0, 0.2), 'track', faces=(1, 2, 4) + ends, top_scale=(1.0, 0.85))
        x = xe
    if L <= 1:
        for s in (-1, 1):
            m.box(((x0 + x1) / 2, s * gauge / 2, 0.25), (x1 - x0, 0.09, 0.1), 'steel', faces=(1, 2, 3, 4, 5))


def boxcar(m, L, x, sw, culture_band=False):
    if L == 3:
        m.box((x, 0, 2.2), (8.2, 2.7, 2.6), sw, faces=(1, 2, 3, 4, 5))
        return
    prof = [(1.35, 0.95), (1.35, 3.25), (0.9, 3.52), (-0.9, 3.52), (-1.35, 3.25), (-1.35, 0.95)]
    sws = [sw, 'metal_dark', 'metal_dark', 'metal_dark', sw, 'metal_dark']
    m.loft(prof, [(x - 4.1, 1, 1, 0, 0), (x + 4.1, 1, 1, 0, 0)], sws, swcap=sw)
    if culture_band and L <= 1:
        for s in (-1, 1):
            m.box((x, s * 1.37, 2.95), (8.0, 0.04, 0.32), 'cult_paint')
    if L <= 1:
        for s in (-1, 1):
            m.box((x + 0.2, s * 1.37, 2.0), (1.8, 0.04, 2.0), 'metal_dark')
    m.box((x, 0, 0.75), (8.0, 2.2, 0.3), 'metal_dark', faces=(0, 1, 2, 3, 4, 5) if L == 0 else (0, 1, 2, 4))
    for bx in (x - 2.9, x + 2.9):
        for ax in (-0.8, 0.8):
            for s in (-1, 1):
                if L <= 1 or ax > 0:
                    m.append(wheel(L, (bx + ax, s * 0.72, 0.68), 0.42, 0.12, sw='loco_black'))


def flatcar(m, L, x, containers):
    m.box((x, 0, 0.95), (8.4, 2.5, 0.3), 'metal_dark')
    for k, (cx, sw) in enumerate(containers):
        m.box((x + cx, 0, 2.3), (3.9, 2.4, 2.4), sw)
        if L == 0:
            for s in (-1, 1):
                for r in range(4):
                    m.box((x + cx - 1.5 + r, s * 1.215, 2.3), (0.12, 0.03, 2.2), 'metal_dark')
    if L <= 2:
        for bx in (x - 2.9, x + 2.9):
            for s in (-1, 1):
                m.append(wheel(L, (bx, s * 0.72, 0.62), 0.42, 0.12, sw='loco_black'))


def locomotive(m, L, x):
    """Steam locomotive with tender, facing +X; x = centre of the engine."""
    if L == 3:
        m.box((x, 0, 2.2), (10.0, 2.6, 3.0), 'loco_black', faces=(1, 2, 3, 4, 5))
        m.box((x - 8.0, 0, 1.9), (5.0, 2.7, 2.6), 'loco_black', faces=(1, 2, 3, 4, 5))
        return
    nb = [14, 8, 6][L]
    m.box((x, 0, 1.25), (10.0, 2.4, 0.5), 'metal_dark')
    m.tube((x - 1.8, 0, 2.45), (x + 4.2, 0, 2.45), 0.92, 0.92, nb, 'loco_black', caps=(False, False), smooth=True)
    m.tube((x + 4.2, 0, 2.45), (x + 4.8, 0, 2.45), 0.98, 0.98, nb, 'metal_dark', smooth=True)
    m.tube((x + 3.7, 0, 3.2), (x + 3.7, 0, 4.25), 0.28, 0.36, 8 if L == 0 else 5, 'loco_black', caps=(False, True))
    if L <= 1:
        m.sphere((x + 1.6, 0, 3.35), 0.38, 8 if L == 0 else 5, 3, 'gold', sc=(1, 1, 0.9))
        m.box((x + 4.9, 0, 2.6), (0.1, 0.3, 0.3), 'emit_gold')
        # culture band on the boiler
        m.tube((x + 0.5, 0, 2.45), (x + 0.9, 0, 2.45), 0.95, 0.95, nb, 'cult_paint', caps=(False, False), smooth=True)
    # cab
    m.box((x - 2.8, 0, 2.55), (2.2, 2.6, 2.1), 'loco_black')
    m.box((x - 2.8, 0, 3.7), (2.6, 2.9, 0.18), 'metal_dark')
    if L == 0:
        for s in (-1, 1):
            m.box((x - 2.5, s * 1.31, 2.95), (0.9, 0.03, 0.6), 'glass')
    # cowcatcher
    m.box((x + 5.25, 0, 0.75), (0.9, 2.2, 0.7), 'metal_dark', top_scale=(0.3, 1.0), top_off=(-0.3, 0))
    # driving wheels
    for wx in (x + 2.6, x + 0.8, x - 1.0):
        for s in (-1, 1):
            m.append(wheel(L, (wx, s * 0.95, 0.85), 0.85, 0.14, sw='loco_black'))
    if L <= 1:
        for s in (-1, 1):
            m.box((x + 0.8, s * 1.06, 0.85), (3.8, 0.05, 0.12), 'steel')
    # tender
    m.box((x - 7.2, 0, 1.95), (4.8, 2.6, 2.2), 'loco_black')
    if L <= 1:
        m.box((x - 7.2, 0, 3.12), (4.4, 2.2, 0.3), 'char', top_scale=(0.85, 0.75))
    for wx in (x - 8.6, x - 5.8):
        for s in (-1, 1):
            if L <= 1 or s > 0:
                m.append(wheel(L, (wx, s * 0.95, 0.6), 0.55, 0.12, sw='loco_black'))
    # smoke puff trailing back from the stack
    if L <= 2:
        puffs = [(x + 3.5, 0, 4.9, 0.75), (x + 2.2, 0.15, 5.5, 1.0), (x + 0.5, -0.1, 6.0, 1.25), (x - 1.6, 0.25, 6.3, 1.4)]
        for k, (px, py, pz, r) in enumerate(puffs if L == 0 else puffs[:2] if L == 1 else puffs[:1]):
            m.sphere((px, py, pz), r, [8, 6, 4][L], [5, 4, 3][L], 'smoke', sc=(1.2, 0.9, 0.8))


def traders_modern(L, var):
    """Industry/Atomic traders: a steam freight train (loco, tender, two boxcars, a container flat) on its track."""
    m = MB()
