def warband_slots(rng, cols, rows, dx, dy, skew=0.0, jit=0.15):
    out = []
    for r in range(rows):
        for c in range(cols):
            out.append((-c * dx + r * skew + rng.uniform(-jit, jit), (r - (rows - 1) / 2) * dy + rng.uniform(-jit, jit), c, r))
    return out


def army_ancient(L, var):
    """Stone/Bronze warband: a ragged dark block of spearmen, round hide shields at the front, one tall pennant."""
    rng = random.Random(51)
