    if L == 3:
        lod3_block(m, -4.9, 0.6, 3.8, 1.75, 'cloth_dark')
        m.box((-2.2, 0, 2.2), (5.0, 3.4, 0.9), 'wood_dark', faces=(1, 2, 3, 4, 5), top_scale=(0.9, 0.9))
        pennant(m, (0.6, 0.0, 0), 4.6, 1.6, L=2)
        return m
    r2 = random.Random(17)
    for (x, y, c, r) in slots:
        m.append(human(L, r2, spear=True, shield=(c == 0 or r == 0 or r == 4), scale=r2.uniform(0.95, 1.05)), T(x, y, rz=r2.uniform(-0.12, 0.12)))
