def truck(m, L, x, lead=False):
    """Olive military truck: bonnet, cab, canvas-covered bed (culture canvas on the lead truck)."""
    if L == 3:
        m.box((x + 2.2, 0, 1.4), (2.0, 2.3, 1.9), 'olive', faces=(1, 2, 3, 4, 5))
        m.box((x - 0.9, 0, 1.6), (4.2, 2.4, 2.3), 'cult_cloth' if lead else 'olive_canvas', faces=(1, 2, 3, 4, 5))
        return
    m.box((x, 0, 0.85), (6.4, 1.5, 0.3), 'metal_dark', faces=(1, 2, 3, 4, 5))
    m.box((x + 2.75, 0, 1.3), (1.2, 1.9, 0.9), 'olive', top_scale=(0.95, 0.8))
    m.box((x + 1.6, 0, 1.75), (1.3, 2.2, 1.6), 'olive')
    # glass, lamps and the middle axle are LOD0 only (verify fix 2026-11-19: LOD1 was 62 % of LOD0; ASSETS.md asks ~40 %)
    if L == 0:
        m.box((x + 2.26, 0, 2.15), (0.03, 1.8, 0.55), 'glass')
        for s in (-1, 1):
            m.box((x + 1.65, s * 1.11, 2.15), (0.8, 0.03, 0.5), 'glass')
            m.box((x + 3.36, s * 0.7, 1.35), (0.04, 0.22, 0.18), 'emit_gold')
    m.box((x - 1.2, 0, 1.3), (4.1, 2.35, 0.6), 'olive')
    n = [8, 5, 3][L]
    prof = [(math.cos(math.pi * i / n) * 1.17, math.sin(math.pi * i / n) * 0.75) for i in range(n + 1)]
    prof = prof + [(-1.17, -0.5), (1.17, -0.5)]
    m.loft(prof, [(x - 3.2, 1, 1, 0, 2.1), (x + 0.8, 1, 1, 0, 2.1)], 'cult_cloth' if lead else 'olive_canvas', smooth=(L == 0))
    for wx in (x + 2.6, x - 1.0, x - 2.3):
        for s in (-1, 1):
            if L == 0 or wx != x - 1.0:
                m.append(wheel(L, (wx, s * 0.98, 0.5), 0.5, 0.36, sw='rubber'))


