        m.slab([(-16.2, -5.5, 3.2), (-14.8, -5.5, 3.2), (-11.5, 0, 3.0), (-14.8, 5.5, 3.2), (-16.2, 5.5, 3.2), (-15.5, 0, 3.0)], 0.2, 'hull_white')
