def rocket_body(m, L, z0, n=None):
    n = n or [24, 12, 8, 6][L]
    prof = [(1.25, z0 - 1.6, 'metal_dark'), (0.7, z0 + 0.0, 'metal_dark'), (2.0, z0 + 0.0, 'hull_white'), (2.0, z0 + 24.0, 'gold'),
            (2.0, z0 + 25.6, 'hull_white'), (1.8, z0 + 26.0, 'hull_white'), (1.8, z0 + 29.0, 'cult_paint'), (1.8, z0 + 30.6, 'hull_white'),
            (1.8, z0 + 35.0, 'hull_white'), (1.6, z0 + 37.8, 'hull_white'), (1.05, z0 + 40.0, 'hull_white'), (0.35, z0 + 41.6, 'hull_white'), (0.0, z0 + 42.0, 'hull_white')]
    if L >= 2:
        prof = [prof[0], prof[2], prof[3], prof[4], prof[6], prof[7], prof[9], prof[11], prof[12]]
    m.lathe(prof, n, None, cap_bottom=True)
    for k in range(4):
        a = math.pi / 4 + k * math.pi / 2
        d = Vector((math.cos(a), math.sin(a), 0))
        pts = [d * 1.95 + Vector((0, 0, z0 + 0.2)), d * 3.6 + Vector((0, 0, z0 - 0.4)), d * 3.6 + Vector((0, 0, z0 + 1.8)), d * 1.95 + Vector((0, 0, z0 + 6.0))]
        m.slab(pts, 0.18, 'hull_white', sw_edge='gold')


def lattice_tower(m, L, c, w, h, step, sw='lattice', diag=True, open_side=None, rng=None, broken=0.0, bar=0.35):
    """Square lattice tower: 4 columns, a ring of beams every step, X-bracing on the faces."""
    cx, cy = c[0], c[1]
    cs = [(cx - w / 2, cy - w / 2), (cx + w / 2, cy - w / 2), (cx + w / 2, cy + w / 2), (cx - w / 2, cy + w / 2)]
    if L == 3:
        m.box((cx, cy, h / 2), (w, w, h), sw, faces=(1, 2, 3, 4, 5))
        return
    for (x, y) in cs:
        m.beam((x, y, -0.3), (x, y, h), bar * 1.6, bar * 1.6, sw, caps=True)
    lv = int(h // step)
    stride = 1 if L == 0 else 2
    for k in range(1, lv + 1, stride if L <= 1 else 3):
        z = k * step
        for i in range(4):
            if rng and broken and rng.random() < broken:
                continue
            a, b = cs[i], cs[(i + 1) % 4]
            m.beam((a[0], a[1], z), (b[0], b[1], z), bar, bar, sw, caps=False)
            if diag and L == 0 and i != open_side:
                m.beam((a[0], a[1], z - step), (b[0], b[1], z), bar * 0.7, bar * 0.7, sw, caps=False)


def rocket(L, var):
    """Space-age launch. 'Pad': on its mount with an umbilical tower; 'Launch': rising on a white-gold plume."""
    m = MB()
    if var == 'Pad':
        m.box((0, 0, 0.3), (22.0, 22.0, 1.2), 'concrete', faces=(1, 2, 3, 4, 5))
