def reset_scene():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    sc = bpy.context.scene
    sc.unit_settings.system = 'METRIC'
    sc.unit_settings.scale_length = 1.0


def load_img(name, colorspace):
    p = os.path.join(TEXDIR, name + '.png')
    img = bpy.data.images.get(name + '.png') or bpy.data.images.load(p, check_existing=True)
    img.colorspace_settings.name = colorspace
    return img


def make_material(name, culture_hex='#ffffff', night=0.0):
    mat = bpy.data.materials.new(name)
    mat.use_nodes = True
    nt = mat.node_tree
    for n in list(nt.nodes):
        nt.nodes.remove(n)
    out = nt.nodes.new('ShaderNodeOutputMaterial')
    bs = nt.nodes.new('ShaderNodeBsdfPrincipled')
    tD = nt.nodes.new('ShaderNodeTexImage'); tD.image = load_img('T_Unit_Trim_D', 'sRGB')
    tN = nt.nodes.new('ShaderNodeTexImage'); tN.image = load_img('T_Unit_Trim_N', 'Non-Color')
    tO = nt.nodes.new('ShaderNodeTexImage'); tO.image = load_img('T_Unit_Trim_ORM', 'Non-Color')
    tM = nt.nodes.new('ShaderNodeTexImage'); tM.image = load_img('T_Unit_Trim_M', 'Non-Color')
    sO = nt.nodes.new('ShaderNodeSeparateColor')
    sM = nt.nodes.new('ShaderNodeSeparateColor')
    cul = nt.nodes.new('ShaderNodeRGB'); cul.name = 'Culture'
    c = dmtex.hex_lin(culture_hex)
    cul.outputs[0].default_value = (float(c[0]), float(c[1]), float(c[2]), 1.0)
    mix = nt.nodes.new('ShaderNodeMix'); mix.data_type = 'RGBA'; mix.blend_type = 'MULTIPLY'
    nm = nt.nodes.new('ShaderNodeNormalMap')
    em1 = nt.nodes.new('ShaderNodeMath'); em1.operation = 'MULTIPLY'; em1.inputs[1].default_value = 1.3
    em2 = nt.nodes.new('ShaderNodeMath'); em2.operation = 'MULTIPLY_ADD'; em2.inputs[1].default_value = night * 4.0
    L = nt.links
    L.new(tO.outputs['Color'], sO.inputs[0])
    L.new(tM.outputs['Color'], sM.inputs[0])
    L.new(sM.outputs[1], mix.inputs[0])
    L.new(tD.outputs['Color'], mix.inputs[6])
    L.new(cul.outputs[0], mix.inputs[7])
    L.new(mix.outputs[2], bs.inputs['Base Color'])
    L.new(sO.outputs[1], bs.inputs['Roughness'])
    L.new(sO.outputs[2], bs.inputs['Metallic'])
    L.new(tN.outputs['Color'], nm.inputs['Color'])
    L.new(nm.outputs['Normal'], bs.inputs['Normal'])
    L.new(mix.outputs[2], bs.inputs['Emission Color'])
    L.new(sM.outputs[2], em1.inputs[0])
    L.new(sM.outputs[0], em2.inputs[0])
    L.new(em1.outputs[0], em2.inputs[2])
    L.new(em2.outputs[0], bs.inputs['Emission Strength'])
    L.new(bs.outputs[0], out.inputs[0])
    return mat


def to_object(mb, name, mats):
    """MB -> mesh object. UVs are box-projected per face into the face's swatch cell; n-gons are fanned
    into triangles (convex by construction) so tangents export."""
    # final turn: authored facing +X, delivered facing -Y
    R = Matrix.Rotation(-math.pi / 2, 4, 'Z')
    verts = [tuple(R @ p) for p in mb.v]
    faces, fuv, fmat, fsm = [], [], [], []
    for idx, sw, sm in mb.f:
        sw_rec = SWATCHES[sw]
        pts = [Vector(verts[i]) for i in idx]
        n = newell(pts)
        ax = max(range(3), key=lambda k: abs(n[k]))
        a, b = [(1, 2), (0, 2), (0, 1)][ax]
        mpc = sw_rec[5]
        us = [p[a] / mpc for p in pts]
        vs = [p[b] / mpc for p in pts]
        u0, v0 = min(us), min(vs)
        ext = max(max(us) - u0, max(vs) - v0, 1e-6)
        k = 1.0 / ext if ext > 1.0 else 1.0
        # deterministic offset inside the cell so neighbouring faces do not all sample the same corner
        h = (hash((round(u0, 2), round(v0, 2), sw)) % 997) / 997.0
        fu = (1.0 - (max(us) - u0) * k) * h
        fv = (1.0 - (max(vs) - v0) * k) * ((h * 7.31) % 1.0)
        cx, cy = sw % GRID, sw // GRID
        uv = [((cx + 0.06 + 0.88 * ((uu - u0) * k + fu)) / GRID, (cy + 0.06 + 0.88 * ((vv - v0) * k + fv)) / GRID) for uu, vv in zip(us, vs)]
        if len(idx) <= 4:
            parts = [list(range(len(idx)))]
        else:
            parts = [[0, j, j + 1] for j in range(1, len(idx) - 1)]
            # caps with collinear runs (bus ends) fan into zero-area slivers: drop them (verify fix 2026-11-19)
            parts = [pr for pr in parts if (pts[pr[1]] - pts[pr[0]]).cross(pts[pr[2]] - pts[pr[0]]).length > 1e-7] or parts
        for pr in parts:
            faces.append([idx[j] for j in pr])
            fuv.append([uv[j] for j in pr])
            fmat.append(sw_rec[9])
            fsm.append(bool(sm))
    me = bpy.data.meshes.new(name)
    me.from_pydata(verts, [], faces)
    for mt in mats:
        me.materials.append(mt)
    uvl = me.uv_layers.new(name='UVMap')
    for pi, poly in enumerate(me.polygons):
        poly.material_index = fmat[pi]
        poly.use_smooth = fsm[pi]
        for li, c in zip(poly.loop_indices, fuv[pi]):
            uvl.data[li].uv = c
    me.update()
    ob = bpy.data.objects.new(name, me)
    return ob


def normals_check(mb):
    bad = tot = 0
    for f0, f1, c, ck in mb.parts:
        if not ck:
            continue
        for fi in range(f0, f1):
            idx = mb.f[fi][0]
            pts = [mb.v[i] for i in idx]
            n = newell(pts)
            if n.length < 1e-9:
                continue
            cen = sum(pts, Vector()) / len(pts)
            tot += 1
            if isinstance(ck, list):
                # bent tube: compare against the closest point on its axis polyline
                best = None
                for q0, q1 in zip(ck[:-1], ck[1:]):
                    seg = q1 - q0
                    t = max(0.0, min(1.0, (cen - q0).dot(seg) / max(seg.length_squared, 1e-9)))
                    q = q0 + seg * t
                    if best is None or (cen - q).length < (cen - best).length:
                        best = q
                ref = best
            elif ck == 'lathe':
                ref = Vector((c.x, c.y, cen.z))
            else:
                ref = c
            d = cen - ref
            if n.dot(d) < -0.05 * n.length * d.length:
                bad += 1
    return bad, tot


def build_asset(a, mats, col):
    root = bpy.data.objects.new(a['name'], None)
    root['fbx_type'] = 'LodGroup'
    col.objects.link(root)
    info = dict(tris=[], bad_normals=0)
    lods = []
    frame = None
    if a['ring'] == 'auto':
        m0 = a['fn'](0, a['var'])
        xs = [p.x for p in m0.v]
        ys = [p.y for p in m0.v]
        frame = ((min(xs) + max(xs)) / 2, (min(ys) + max(ys)) / 2, (max(xs) - min(xs)) / 2, max((max(ys) - min(ys)) / 2, 1.2))
    for L in range(4):
        mb = a['fn'](L, a['var'])
        if frame is not None:
            mb = MB().append(mb, T(-frame[0], -frame[1]))
            ground_ring(mb, L, frame[2], frame[3])
        bad, tot = normals_check(mb)
        info['bad_normals'] += bad
        if L == 0:
            info['normal_faces'] = tot
        ob = to_object(mb, '%s_LOD%d' % (a['name'], L), mats)
        col.objects.link(ob)
        ob.parent = root
        info['tris'].append(sum(len(p.vertices) - 2 for p in ob.data.polygons))   # what is exported
        if L > 0:
            ob.hide_render = True
            ob.hide_viewport = True
        lods.append(ob)
    me = lods[0].data
    xs = [v.co.x for v in me.vertices]
    ys = [v.co.y for v in me.vertices]
    zs = [v.co.z for v in me.vertices]
    info['bbox'] = [min(xs), min(ys), min(zs), max(xs), max(ys), max(zs)]
    info['root'] = root
    info['lods'] = lods
    return info


def export_fbx(info, a):
    os.makedirs(EXPDIR, exist_ok=True)
    bpy.ops.object.select_all(action='DESELECT')
    root = info['root']
    for ob in [root] + info['lods']:
        ob.hide_viewport = False
        ob.hide_set(False)
        ob.select_set(True)
    bpy.context.view_layer.objects.active = root
    path = os.path.join(EXPDIR, a['name'] + '.fbx')
    bpy.ops.export_scene.fbx(filepath=path, use_selection=True, object_types={'EMPTY', 'MESH'},
                             mesh_smooth_type='FACE', use_tspace=True, add_leaf_bones=False, bake_anim=False,
                             use_mesh_modifiers=True, path_mode='STRIP', axis_forward='-Z', axis_up='Y',
                             apply_unit_scale=True, apply_scale_options='FBX_SCALE_NONE')
    for ob in info['lods'][1:]:
        ob.hide_viewport = True
    return path


def manifest_entry(a, info):
    b = info['bbox']
    t = info['tris']
    e = {
        'footprint_m': [round(b[3] - b[0], 2), round(b[4] - b[1], 2)],
        'height_m': round(b[5] - max(0.0, b[2]) if b[2] > -0.5 else b[5] - b[2], 2),
        'bbox_m': [round(x, 2) for x in b],
        'triangles': {'LOD%d' % i: t[i] for i in range(4)},
        'lod_ratio': [round(t[i] / t[0], 3) for i in range(4)],
        'lod_screen_sizes': [1.0, 0.35, 0.12, 0.04],
        'materials': ['M_Unit_Structure', 'M_Unit_Roof', 'M_Unit_Detail'],
        'textures': ['T_Unit_Trim_D', 'T_Unit_Trim_N', 'T_Unit_Trim_ORM', 'T_Unit_Trim_M'],
        'culture_variants': ['MI_Unit_Detail_%s' % c[0] for c in CULTURES],
        'states': a['states'],
        'unit_type': a['unit'],
        'ages': a['ages'],
        'age_names': [AGE_NAMES[i] for i in a['ages']],
        'description': a['desc'],
        'ground_ring': {'auto': 'built in round the footprint (Detail slot, culture tint)', 'own': 'built in (Detail slot, culture tint)' if a['unit'] != 'Ring' else 'this mesh is the ring', 'none': 'none: place SM_Unit_GroundRing_A on the ground below, scaled about x1.9 so it clears the wingspan (as in the previews)'}[a['ring']],
        'flying': a['flying'],
        'budget': a['budget'],
        'facing': '-Y in Blender (+X in Unreal)',
        'pivot': 'centre of the footprint at ground level' + ('; craft hovers above it' if a['short'] in ('settlers-space', 'army-space') else ''),
        'licence': 'original',
        'script': SCRIPT_REL,
        'export': 'art/units-land/export/%s.fbx' % a['name'],
    }
    if a['short'] in SHEET_PX:
        tall = a['unit'] in ('Launch', 'Ark')
        e['sheet_px'] = SHEET_PX[a['short']]
        e['sheet_measure'] = 'height' if tall else 'length'
        e['sheet_metres'] = round((b[5] - max(b[2], 0)) if tall else max(b[3] - b[0], b[4] - b[1]), 2)
    return e


def write_manifest(entries):
    path = os.path.join(HERE, 'manifest.json')
    data = {}
    if os.path.exists(path):
        try:
            with open(path, encoding='utf-8') as f:
                data = json.load(f)
        except Exception:
            data = {}
    meshes = data.get('meshes', {})
    meshes.update(entries)
    data = {
        'family': 'Unit',
        'folder': 'art/units-land',
        'generated': time.strftime('%Y-%m-%d'),
        'script': SCRIPT_REL,
        'licence': 'original (procedural, made in Blender 5.2 by script; no external inputs)',
        'material_model': {
            'master': 'M_Unit_Trim (one master; slots Structure, Roof, Detail all use the same trim sheet)',
            'slots': {'0 Structure': 'figures, animals, wood, metal, glass', '1 Roof': 'canvas, white hulls, smoke, robes', '2 Detail': 'culture-coloured cloth and paint, the ground ring, gold, emissive glows'},
            'base_color': 'T_D * lerp(1, CultureColor, T_M.G)',
            'emissive': 'BaseColor * (T_M.B * EmissiveStrength + T_M.R * NightFactor * WindowStrength)',
            'masks_T_M': {'R': 'night windows (vehicle glass)', 'G': 'culture tint mask', 'B': 'always-on glow (halo, engines, plume, lamps, ring at 0.12)'},
            'ORM': 'R ambient occlusion, G roughness, B metallic (linear)',
            'normal': 'OpenGL (+Y up); flip green on import into Unreal',
            'instances': ['MI_Unit_Structure', 'MI_Unit_Roof'] + ['MI_Unit_Detail_%s (CultureColor %s)' % c for c in CULTURES],
        },
        'cultures': {c[0]: c[1] for c in CULTURES},
        'sim_mapping': {
            'Settler': {'0-1': 'SM_Unit_Settlers_Ancient', '2-3': 'SM_Unit_Settlers_Classical', '4-5': 'SM_Unit_Settlers_Modern', '6': 'SM_Unit_Settlers_Space'},
            'Trader': {'0-1': 'SM_Unit_Traders_Ancient', '2-3': 'SM_Unit_Traders_Classical', '4-5': 'SM_Unit_Traders_Modern', '6': 'SM_Unit_Traders_Space'},
            'Army': {'0-1': 'SM_Unit_Army_Ancient', '2-3': 'SM_Unit_Army_Classical', '4-5': 'SM_Unit_Army_Modern', '6': 'SM_Unit_Army_Space'},
            'Prophet': {'0-6': 'SM_Unit_Prophet_A'},
            'decorative air traffic': {'5': 'SM_Unit_Aircraft_Prop', '5-6': 'SM_Unit_Aircraft_Jet', 'ring': 'SM_Unit_GroundRing_A'},
            'space launch / ark': {'launch': 'SM_Unit_Rocket_A_Pad -> SM_Unit_Rocket_A_Launch', 'ark': 'SM_Unit_Ark_A_Construction / _Intact / _Damaged'},
        },
        'meshes': dict(sorted(meshes.items())),
    }
    # relative scale that makes every unit as long on screen as on the silhouette sheet (settlers-ancient = 1)
    ref = meshes.get('SM_Unit_Settlers_Ancient')
    if ref and ref.get('sheet_metres'):
        k0 = ref['sheet_px'] / ref['sheet_metres']
        for nm, e in meshes.items():
            if e.get('sheet_metres'):
                e['suggested_unit_scale'] = round(e['sheet_px'] / e['sheet_metres'] / k0, 3)
        data['suggested_unit_scale_note'] = ('The units layer draws every unit at one distance-dependent scale. Multiply by '
                                             'suggested_unit_scale per mesh to match the silhouette sheet, where a freight '
                                             'train is no longer than a settler band (the ark and launch stay landmarks).')
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=1)
    print('manifest', path, len(meshes), 'meshes')


# ============================================================================ preview rig

def setup_rig():
    sc = bpy.context.scene
    for eng in ('BLENDER_EEVEE', 'BLENDER_EEVEE_NEXT'):
        try:
            sc.render.engine = eng
            break
        except TypeError:
            continue
    sc.render.resolution_x, sc.render.resolution_y = 1280, 720
    sc.render.resolution_percentage = 100
    sc.render.image_settings.file_format = 'PNG'
    try:
        sc.eevee.taa_render_samples = 48
    except Exception:
        pass
    for attr, val in (('use_shadows', True), ('shadow_ray_count', 2), ('shadow_step_count', 8), ('use_raytracing', True)):
        try:
            setattr(sc.eevee, attr, val)
        except Exception:
            pass
    try:
        sc.view_settings.view_transform = 'AgX'
        sc.view_settings.look = 'AgX - Medium High Contrast'
    except Exception:
        pass
    sc.view_settings.exposure = 0.0
    # world: cool sky fill
    w = bpy.data.worlds.new('PreviewSky')
    sc.world = w
    w.use_nodes = True
    bg = w.node_tree.nodes.get('Background')
    bg.inputs[0].default_value = (0.30, 0.42, 0.68, 1.0)
    bg.inputs[1].default_value = 0.7
    # sun: 20 deg elevation, warm, from the camera's left and a little behind the subject
    ld = bpy.data.lights.new('Sun', 'SUN')
    ld.energy = 5.5
    ld.color = (1.0, 0.78, 0.52)
    ld.angle = math.radians(1.2)
    sun = bpy.data.objects.new('Sun', ld)
    sc.collection.objects.link(sun)
    el, az = math.radians(20), math.radians(150)
    d = Vector((math.cos(el) * math.cos(az), math.cos(el) * math.sin(az), math.sin(el)))
    sun.rotation_euler = d.to_track_quat('Z', 'Y').to_euler()
    # neutral ground with a little breakup
    gm = bpy.data.materials.new('PreviewGround')
    gm.use_nodes = True
    nt = gm.node_tree
    bs = nt.nodes.get('Principled BSDF')
    noise = nt.nodes.new('ShaderNodeTexNoise')
    noise.inputs['Scale'].default_value = 0.08
    noise.inputs['Detail'].default_value = 8.0
    ramp = nt.nodes.new('ShaderNodeValToRGB')
    ramp.color_ramp.elements[0].color = (0.16, 0.15, 0.09, 1)
    ramp.color_ramp.elements[1].color = (0.24, 0.21, 0.13, 1)
    tc = nt.nodes.new('ShaderNodeTexCoord')
    nt.links.new(tc.outputs['Object'], noise.inputs['Vector'])
    nt.links.new(noise.outputs['Fac'], ramp.inputs['Fac'])
    nt.links.new(ramp.outputs['Color'], bs.inputs['Base Color'])
    bs.inputs['Roughness'].default_value = 0.95
    bpy.ops.mesh.primitive_plane_add(size=12000, location=(0, 0, -0.02))
    g = bpy.context.active_object
    g.name = 'PreviewGround'
    g.data.materials.append(gm)
    cam_d = bpy.data.cameras.new('Cam')
    cam_d.lens = 50
    cam_d.sensor_width = 36
    cam_d.clip_start = 0.5
    cam_d.clip_end = 20000
    cam = bpy.data.objects.new('Cam', cam_d)
    sc.collection.objects.link(cam)
    sc.camera = cam
    # 1.8 m reference figure (pale grey)
    rm = bpy.data.materials.new('PreviewRef')
    rm.use_nodes = True
    rm.node_tree.nodes.get('Principled BSDF').inputs['Base Color'].default_value = (0.6, 0.6, 0.6, 1)
    bpy.ops.mesh.primitive_cylinder_add(vertices=8, radius=0.2, depth=1.56, location=(0, 0, 0.78))
    ref = bpy.context.active_object
    ref.name = 'Ref1p8'
    ref.data.materials.append(rm)
    bpy.ops.mesh.primitive_uv_sphere_add(segments=12, ring_count=6, radius=0.12, location=(0, 0, 1.68))
    hd = bpy.context.active_object
    hd.data.materials.append(rm)
    bpy.ops.object.select_all(action='DESELECT')
    hd.select_set(True)
    ref.select_set(True)
    bpy.context.view_layer.objects.active = ref
    bpy.ops.object.join()
    # after the join the mesh spans z -0.78..1.02 about the object origin (0, 0, 0.78): lift the data so the feet
    # sit at z 0 and the head top at 1.80 once the object is moved to the ground (verify fix 2026-11-19: it was
    # shifted down, which buried the figure so only its head showed in the 40 m previews)
    ref.data.transform(Matrix.Translation((0, 0, 0.78)))
    ref.location = (0, 0, 0)
    return cam, ref


def aim(cam, target, dist, el_deg, az_deg):
    el, az = math.radians(el_deg), math.radians(az_deg)
    d = Vector((math.cos(el) * math.cos(az), math.cos(el) * math.sin(az), math.sin(el)))
    cam.location = Vector(target) + d * dist
    cam.rotation_euler = (Vector(target) - cam.location).to_track_quat('-Z', 'Y').to_euler()


def render_asset(a, info, cam, ref, det_mats, views):
    sc = bpy.context.scene
    root = info['root']
    lod0 = info['lods'][0]
    b = info['bbox']
    size = max(b[3] - b[0], b[4] - b[1], b[5] - max(b[2], 0))
    alt = 0.0
    if a['flying']:
        alt = 24.0 if a['unit'] == 'Air' else 0.0
    lod0.hide_render = False
    lod0.location = (0, 0, alt)
    extra = []
    ring = None
    if a['unit'] == 'Air':
        rg = BY_SHORT['groundring']
        mb = rg['fn'](0, None)
        ring = to_object(mb, 'PreviewRing', [lod0.data.materials[0], lod0.data.materials[1], lod0.data.materials[2]])
        ring.scale = (1.9, 1.9, 1.0)
        sc.collection.objects.link(ring)
    cz = alt + (b[5] - max(b[2], 0)) * (0.5 if (b[5] - max(b[2], 0)) > 20 else 0.35)
    out = []
    fov = 2 * math.atan(18 / 50)
    vfov = 2 * math.atan(18 * 720 / 1280 / 50)
    height = b[5] - max(b[2], 0)
    for view in views:
        for e in extra:
            e.hide_render = True
        if view == '40m':
            dist = max(40.0, size * 0.75 / math.tan(fov / 2), height * 0.75 / math.tan(vfov / 2))
            ref.hide_render = False
            ref.location = (b[0] - 3.0, b[1] - 1.0, 0.0)
            if a['unit'] in ('Ark',):
                ref.location = (-36.0, -42.0, 0.0)
            aim(cam, (0, 0, cz), dist, 26, 235)
            if dist > 40.5:
                print('  40m view pulled back to %.0f m to frame the asset' % dist)
        elif view == '15m':
            ref.hide_render = True
            aim(cam, (0, 0, cz), 16.0 if size < 25 else size * 0.6, 22, 235)
        elif view == '300m':
            ref.hide_render = True
            aim(cam, (0, 0, cz), 300.0, 38, 235)
        else:
            ref.hide_render = True
            # six culture variants in a row at the far view
            if not extra:
                for k in range(1, 6):
                    o = lod0.copy()
                    o.parent = None
                    sc.collection.objects.link(o)
                    extra.append(o)
                    if ring is not None:
                        r2 = ring.copy()
                        sc.collection.objects.link(r2)
                        extra.append(r2)
            sp = max(45.0, max(b[3] - b[0], b[4] - b[1]) * 1.35)
            k = 0
            objs = [lod0] + [e for e in extra if e.data == lod0.data]
            rings = [ring] + [e for e in extra if ring is not None and e.data == ring.data]
            for k, o in enumerate(objs):
                o.hide_render = False
                o.location = (sp * (k - 2.5), sp * 0.25 * ((k % 2) * 2 - 1), alt)
                if k > 0:
                    o.material_slots[2].link = 'OBJECT'
                    o.material_slots[2].material = det_mats[k]
            if ring is not None:
                for k, r in enumerate(rings):
                    r.hide_render = False
                    r.location = (sp * (k - 2.5), sp * 0.25 * ((k % 2) * 2 - 1), 0.0)
                    if k > 0:
                        r.material_slots[2].link = 'OBJECT'
                        r.material_slots[2].material = det_mats[k]
            aim(cam, (0, 0, cz), 1000.0, 45, 235)
        path = os.path.join(OUTDIR or SHOTS, 'asset-units-land-%s-%s.png' % (a['short'], view))
        sc.render.filepath = path
        t0 = time.time()
        bpy.ops.render.render(write_still=True)
        print('  rendered %s (%.1f s)' % (os.path.basename(path), time.time() - t0))
        out.append(path)
        if view == '1km':
            for o in objs:
                o.location = (0, 0, alt)
    for e in extra:
        bpy.data.objects.remove(e)
    if ring is not None:
        bpy.data.objects.remove(ring)
    lod0.hide_render = True
    return out


# ============================================================================ main

def main():
    argv = sys.argv[sys.argv.index('--') + 1:] if '--' in sys.argv else []
    do_build = '--build' in argv
    do_tex = '--textures' in argv
    do_render = '--render' in argv
    sel = None
    views = ['40m', '300m', '1km']
    if '--assets' in argv:
        sel = argv[argv.index('--assets') + 1].split(',')
    if '--outdir' in argv:
        global OUTDIR
        OUTDIR = argv[argv.index('--outdir') + 1]
    if '--views' in argv:
        views = argv[argv.index('--views') + 1].split(',')
    if not (do_build or do_render or do_tex):
        do_build = True
    reset_scene()
    need = [os.path.join(TEXDIR, 'T_Unit_Trim_%s.png' % k) for k in ('D', 'N', 'ORM', 'M')]
    if do_tex or not all(os.path.exists(p) for p in need):
        build_textures()
    mats = [make_material('M_Unit_' + s) for s in SLOTS]
    det = [mats[2]] + [make_material('PV_Detail_%s' % c[0], c[1]) for c in CULTURES[1:]]
    mats[2].node_tree.nodes['Culture'].outputs[0].default_value = tuple(float(x) for x in dmtex.hex_lin(CULTURES[0][1])) + (1.0,)
    todo = [a for a in ASSETS if sel is None or a['short'] in sel]
    entries = {}
    infos = {}
    for a in todo:
        col = bpy.data.collections.new(a['name'])
        bpy.context.scene.collection.children.link(col)
        t0 = time.time()
        info = build_asset(a, mats, col)
        infos[a['short']] = info
        t = info['tris']
        flag = ''
        if info['bad_normals']:
            flag = '  WARN %d faces point inward' % info['bad_normals']
        print('%-30s tris %s ratios %s bbox z %.2f..%.2f  (%.1f s)%s' % (a['name'], t, [round(x / t[0], 2) for x in t], info['bbox'][2], info['bbox'][5], time.time() - t0, flag))
        if do_build:
            export_fbx(info, a)
            entries[a['name']] = manifest_entry(a, info)
    if do_build:
        write_manifest(entries)
        if sel is None:
            bpy.context.preferences.filepaths.save_version = 0   # no .blend1 backups in the repo
            bpy.ops.wm.save_as_mainfile(filepath=os.path.join(HERE, 'units-land.blend'), compress=True)
    if do_render:
        cam, ref = setup_rig()
        for inf in infos.values():
            for ob in inf['lods']:
                ob.hide_render = True
        for a in todo:
            print('render', a['name'])
            render_asset(a, infos[a['short']], cam, ref, det, views)


if __name__ == '__main__':
    main()
